function firstIndexSeqGreaterThan(arr: Message[], value: number): number {
  let lo = 0, hi = arr.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid]!.seq <= value) lo = mid + 1; else hi = mid;
  }
  return lo;
}

function firstIndexSeqAtLeast(arr: Message[], value: number): number {
  let lo = 0, hi = arr.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid]!.seq < value) lo = mid + 1; else hi = mid;
  }
  return lo;
}

