import type { Messenger } from "../src/index.js";

export function unreadCount(messenger: Messenger, conversationId: string, userId: string): number {
  let count = 0;
  let cursor: string | undefined;
  do {
    const page = messenger.getMessages(conversationId, userId, { limit: 200, ...(cursor ? { cursor } : {}) });
    for (const m of page.items) {
      const receipt = m.receipts[userId];
      if (receipt && receipt.status !== "read") count++;
    }
    cursor = page.nextCursor ?? undefined;
  } while (cursor);
  return count;
}

