import { describe, expect, it } from "vitest";
import { setup } from "../test/helpers.js";

describe("deleteMessage idempotency", () => {
  it("a second delete keeps the original deletedAt, even after time has genuinely moved forward", async () => {
    const { messenger, clock } = setup();
    const conv = messenger.createDirectConversation("u1", "u2");
    const m = await messenger.sendMessage(conv.id, "u1", "oops, wrong chat", "c1");

    const first = await messenger.deleteMessage(conv.id, "u1", m.id);
    clock.advance(10_000); // move time forward so a re-stamp would be detectable
    const second = await messenger.deleteMessage(conv.id, "u1", m.id);

    expect(second.deletedAt).toBe(first.deletedAt); // not re-stamped
    expect(second.body).toBe("");
  });
});

