import type { Messenger } from "../src/index.js";

export function getConversationsWithUnread(messenger: Messenger, conversationIds: string[], userId: string): string[] {
  const result: string[] = [];
  for (const conversationId of conversationIds) {
    let hasUnread = false;
    let cursor: string | undefined;
    do {
      const page = messenger.getMessages(conversationId, userId, { limit: 200, ...(cursor ? { cursor } : {}) });
      if (page.items.some((m) => m.receipts[userId] && m.receipts[userId]!.status !== "read")) {
        hasUnread = true;
        break;
      }
      cursor = page.nextCursor ?? undefined;
    } while (cursor);
    if (hasUnread) result.push(conversationId);
  }
  return result;
}

