import type { Messenger } from "../src/index.js";

export function unreadCountByMember(messenger: Messenger, conversationId: string): Map<string, number> {
  const conv = messenger.get(conversationId);
  if (!conv) throw new Error(`no conversation ${conversationId}`);
  const counts = new Map<string, number>(conv.members.map((m) => [m.userId, 0]));
  for (const member of conv.members) {
    let cursor: string | undefined;
    do {
      const page = messenger.getMessages(conversationId, member.userId, { limit: 200, ...(cursor ? { cursor } : {}) });
      for (const m of page.items) {
        const receipt = m.receipts[member.userId];
        if (receipt && receipt.status !== "read") counts.set(member.userId, counts.get(member.userId)! + 1);
      }
      cursor = page.nextCursor ?? undefined;
    } while (cursor);
  }
  return counts;
}

